def control(obs):
    view = obs.get('view', {})
    left = view.get('left_rail', [])
    right = view.get('right_rail', [])
    def at(points, u):
        if not points: return None
        pts = sorted(points, key=lambda p: p[0])
        for a, b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0] and b[0] != a[0]:
                return a[1] + (b[1]-a[1])*(u-a[0])/(b[0]-a[0])
        return min(pts, key=lambda p: abs(p[0]-u))[1]
    centers = []
    for u in (2.5, 3.5, 4.5, 5.5):
        l, r = at(left, u), at(right, u)
        if l is not None and r is not None: centers.append((u, (l+r)/2))
    lateral, slope = 0.0, 0.0
    if centers:
        lateral = centers[0][1]
        if len(centers) > 1: slope = (centers[-1][1]-centers[0][1])/(centers[-1][0]-centers[0][0])
    hitch = obs.get('hitch_deg', 0.0)
    steer = max(-24.0, min(24.0, 0.72*hitch - 19.0*lateral - 24.0*slope))
    speed = -0.65 if abs(hitch) <= 18 else -0.40
    return (steer, speed, 180.0)

