def control(obs):
    # Recover from the rail contact, then reverse through the visible right turn.
    if obs.get('t', 0) < 3.0 or obs.get('status') == 'PINNED':
        return (0.0, 0.45, 180.0)
    view = obs.get('view', {})
    left = view.get('left_rail', [])
    right = view.get('right_rail', [])
    def interp(points, u):
        if not points: return None
        pts = sorted(points, key=lambda p: p[0])
        if u < pts[0][0] or u > pts[-1][0]: return None
        for a,b in zip(pts,pts[1:]):
            if a[0] <= u <= b[0] and b[0] != a[0]:
                return a[1] + (b[1]-a[1])*(u-a[0])/(b[0]-a[0])
        return None
    # Keep the trailer's rear inside the rail that is visible; when the bend
    # hides one rail, follow the visible rail's local trajectory conservatively.
    look = 1.3
    l, r = interp(left, look), interp(right, look)
    if l is not None and r is not None:
        center=(l+r)/2
        width=l-r
        error=center
    elif l is not None:
        error=l-1.0
    elif r is not None:
        error=r+1.0
    else:
        error=0.0
    # At positive course curvature into our right, steering left moves the
    # trailer rear right while reversing. Hitch feedback damps articulation.
    steer=max(-18.0,min(18.0, -12.0*error + 0.65*obs.get('hitch_deg',0.0)))
    if abs(obs.get('hitch_deg',0.0)) > 20:
        steer=max(-12.0,min(12.0,0.85*obs['hitch_deg']))
    return (steer,-0.32,180.0)

