def control(obs):
    # Clear the pinned corner with a sustained forward pull.
    if obs.get('status') == 'PINNED' or obs.get('t', 0.0) < 102.0:
        return (0.0, 0.65, 180.0)
    view = obs.get('view', {})
    left = view.get('left_rail', [])
    right = view.get('right_rail', [])
    def interp(points, u):
        pts = sorted(points, key=lambda p: p[0])
        if len(pts) < 2 or u < pts[0][0] or u > pts[-1][0]: return None
        for a, b in zip(pts, pts[1:]):
            if a[0] <= u <= b[0] and b[0] > a[0]:
                return a[1] + (b[1]-a[1])*(u-a[0])/(b[0]-a[0])
        return None
    samples = []
    for u in (0.5, 1.5, 2.5):
        l, r = interp(left, u), interp(right, u)
        if l is not None and r is not None: samples.append((u, (l+r)/2))
    h = obs.get('hitch_deg', 0.0)
    if samples:
        e = samples[0][1]
        slope = (samples[-1][1]-samples[0][1])/(samples[-1][0]-samples[0][0]) if len(samples) > 1 else 0.0
        steer = 8.0 - 5.0*e - 8.0*slope + 0.45*h
    else:
        steer = 12.0 + 0.45*h
    steer = max(-24.0, min(28.0, steer))
    return (steer, -0.12, 180.0)

