import math
def control(obs):
    view=obs.get('view',{})
    def parse(seq):
        out=[]
        for p in seq or []:
            try:
                if isinstance(p,dict): u=float(p.get('u',p.get('x',0))); v=float(p.get('v',p.get('y',0)))
                else: u,v=float(p[0]),float(p[1])
                out.append((u,v))
            except: pass
        return sorted(out)
    L=parse(view.get('left_rail',[])); R=parse(view.get('right_rail',[]))
    def interp(seq,u):
        if len(seq)<2: return None
        if u<=seq[0][0]: return seq[0][1]
        if u>=seq[-1][0]: return seq[-1][1]
        for (a,x),(b,y) in zip(seq,seq[1:]):
            if a<=u<=b: return x+(y-x)*(u-a)/(b-a)
        return None
    vals=[]
    for u in (3.0,4.5,6.0):
        l=interp(L,u); r=interp(R,u)
        if l is not None and r is not None: vals.append((u,(l+r)/2))
    h=float(obs.get('hitch_deg',0))
    steer=0.0
    if vals:
        u,v=vals[min(1,len(vals)-1)]
        steer=-max(-24,min(24,math.degrees(math.atan2(v,u))*0.48))
    steer+=max(-12,min(12,0.42*h))
    steer=max(-30,min(30,steer))
    return steer,-0.38,180

