def interp(points, u):
    pts = sorted((float(p[0]), float(p[1])) for p in points if len(p) >= 2)
    if not pts: return None
    if u <= pts[0][0]: return pts[0][1]
    if u >= pts[-1][0]: return pts[-1][1]
    for (u0,v0),(u1,v1) in zip(pts,pts[1:]):
        if u0 <= u <= u1:
            f=(u-u0)/max(1e-6,u1-u0)
            return v0+f*(v1-v0)
    return None
def control(obs):
    view=obs.get('view',{})
    left=view.get('left_rail',[])
    right=view.get('right_rail',[])
    # Use the corridor centre at a short lookahead; avoid relying on hitch feedback alone.
    targets=[]
    for u in (0.0,2.0,4.0,6.0):
        a=interp(left,u); b=interp(right,u)
        if a is not None and b is not None:
            targets.append((u,(a+b)*0.5))
    steer=0.0
    if targets:
        v0=targets[0][1]
        vf=targets[-1][1]
        steer=-(8.0*v0+18.0*(vf-v0))
    h=float(obs.get('hitch_deg',0.0))
    steer += 1.2*h
    steer=max(-16.0,min(16.0,steer))
    return (steer,-0.30,180.0)

