        if a is not None and b is not None:
            centers.append((u,0.5*(a+b)))
    steer=0.0
    if len(centers)>=2:
        near=min(centers,key=lambda p:abs(p[0]-0.5))
        far=min(centers,key=lambda p:abs(p[0]-3.0))
        slope=(far[1]-near[1])/max(1.0,far[0]-near[0])
        steer=2.0*near[1]+18.0*slope
    h=float(obs.get('hitch_deg',0.0))
    steer += 0.45*h
    steer=max(-18.0,min(18.0,steer))
    return (steer,-0.16,180.0)

